import java.util.*
import kotlin.math.pow

class V62CreditRegistrationActivity:AppCompatActivity(){
 private val store by lazy{V5LocalStore(this)};private val draft by lazy{getSharedPreferences("v62_credit_draft",MODE_PRIVATE)};private val d get()=resources.displayMetrics.density;private lateinit var root:LinearLayout;private var selected:JSONObject?=null;private var step=1;private var docUri=""
 private fun i(h:String)=ArthSaathiV62Design.input(this,h);private fun add(v:View,t:Int=7)=ArthSaathiV62Design.add(root,v,t)
 override fun onCreate(b:Bundle?){super.onCreate(b);window.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);render()}
 private fun render(){root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(ArthSaathiV62Design.dp(16,d),ArthSaathiV62Design.dp(10,d),ArthSaathiV62Design.dp(16,d),ArthSaathiV62Design.dp(28,d));setBackgroundColor(ArthSaathiV62Design.BG)};add(ArthSaathiV62Design.title(this,"Register Financial Relationship","Search • Verify • Agree • Record"),2);add(ArthSaathiV62Design.text(this,"Search or create the counterparty inside this relationship. History is disclosed only after consent and OTP.",10f,ArthSaathiV62Design.MUTED),5);add(ArthSaathiV62Design.text(this,"STEP $step OF 4",10f,ArthSaathiV62Design.TEAL,true),8);when(step){1->profile();2->terms();3->evidence();4->consent()};setContentView(ScrollView(this).apply{isFillViewport=true;addView(root)})}
 private fun profile(){add(ArthSaathiV62Design.section(this,"1 • RELATIONSHIP & COUNTERPARTY"),8);val me=Spinner(this).apply{adapter=ArrayAdapter(this@V62CreditRegistrationActivity,android.R.layout.simple_spinner_dropdown_item,arrayOf("Lender / Supplier / Seller","Borrower / Buyer","Landlord / Lessor","Tenant / Lessee"))};val cp=Spinner(this).apply{adapter=ArrayAdapter(this@V62CreditRegistrationActivity,android.R.layout.simple_spinner_dropdown_item,arrayOf("Borrower / Buyer","Lender / Supplier / Seller","Tenant / Lessee","Landlord / Lessor"))};add(ArthSaathiV62Design.text(this,"My role",10f,ArthSaathiV62Design.MUTED,true),5);add(me,3);add(ArthSaathiV62Design.text(this,"Counterparty role",10f,ArthSaathiV62Design.MUTED,true),8);add(cp,3);add(ArthSaathiV62Design.button(this,"SEARCH / CREATE COUNTERPARTY",ArthSaathiV62Design.TEAL){chooseCounterparty()},10);selected?.let{add(ArthSaathiV62Design.text(this,"Selected: ${it.optString("name")} • ${it.optString("mobile")}",14f,ArthSaathiV62Design.NAVY,true),8);if(draft.getBoolean("historyConsentVerified",false))add(ArthSaathiV62Design.text(this,historySummary(),11f,ArthSaathiV62Design.NAVY),6)else{add(ArthSaathiV62Design.text(this,"History, outstanding and score remain locked until counterparty history consent + OTP verification.",10f,ArthSaathiV62Design.MUTED),5);add(ArthSaathiV62Design.button(this,"REQUEST HISTORY-CONSENT OTP",ArthSaathiV62Design.TEAL){historyConsent()},7)}};add(ArthSaathiV62Design.button(this,"CONTINUE TO TERMS →",ArthSaathiV62Design.GREEN){if(selected==null)Toast.makeText(this,"Select or create a counterparty first.",Toast.LENGTH_SHORT).show() else if(!draft.getBoolean("historyConsentVerified",false))Toast.makeText(this,"History consent OTP is mandatory before credit terms.",Toast.LENGTH_LONG).show() else {draft.edit().putString("myRole",me.selectedItem.toString()).putString("counterRole",cp.selectedItem.toString()).apply();step=2;render()}},12)}
 private fun chooseCounterparty(){val q=i("Search name / mobile / PAN / Aadhaar / GSTIN / profile ID");val list=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};val w=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;addView(q);addView(list)};val dlg=AlertDialog.Builder(this).setTitle("Registered counterparty").setView(w).setNegativeButton("CANCEL",null).create();fun refresh(){list.removeAllViews();val x=q.text.toString().trim().lowercase();val rows=store.all("profiles").filter{p->x.isEmpty()||listOf("id","name","mobile","pan","aadhaar","gstin").any{p.optString(it).lowercase().contains(x)}};if(rows.isEmpty())list.addView(ArthSaathiV62Design.button(this,"CREATE COUNTERPARTY IN THIS TRANSACTION",ArthSaathiV62Design.TEAL){dlg.dismiss();createCounterparty()}) else rows.take(15).forEach{p->list.addView(ArthSaathiV62Design.button(this,"${p.optString("name")} • ${p.optString("mobile")}\n${p.optString("id")}",ArthSaathiV62Design.NAVY){dlg.dismiss();selected=p;draft.edit().putBoolean("historyConsentVerified",false).apply();render()})}};q.addTextChangedListener(object:android.text.TextWatcher{override fun beforeTextChanged(s:CharSequence?,a:Int,b:Int,c:Int){};override fun onTextChanged(s:CharSequence?,a:Int,b:Int,c:Int){refresh()};override fun afterTextChanged(e:android.text.Editable?){}});dlg.show();refresh()}
 private fun createCounterparty(){val n=i("Name / business name *");val m=i("Mobile *");val pan=i("PAN");val gst=i("GSTIN");val w=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;addView(n);addView(m);addView(pan);addView(gst)};AlertDialog.Builder(this).setTitle("Create within this transaction").setView(w).setNegativeButton("CANCEL",null).setPositiveButton("CREATE"){_,_->if(n.text.length>=2&&V5Validation.mobile(m.text.toString())){selected=JSONObject().apply{put("id",ArthSaathiV62Core.id("CP"));put("name",n.text.toString());put("mobile",m.text.toString());put("pan",pan.text.toString().uppercase());put("gstin",gst.text.toString().uppercase())};store.add("profiles",selected!!);draft.edit().putBoolean("historyConsentVerified",false).apply();render()}else Toast.makeText(this,"Enter valid name and mobile.",Toast.LENGTH_SHORT).show()}.show()}
 private fun historyConsent(){val mobile=selected?.optString("mobile").orEmpty();if(mobile.isBlank()){Toast.makeText(this,"A valid counterparty mobile number is required.",Toast.LENGTH_LONG).show();return};val otp=(100000..999999).random();val entry=i("Enter 6-digit OTP");val dlg=AlertDialog.Builder(this).setTitle("History-sharing consent").setMessage("The counterparty is asked to consent to sharing recorded financial history, outstanding behaviour and internal ArthSaathi score for this proposed credit relationship.\n\nDemo OTP: $otp").setView(entry).setNegativeButton("DECLINE",null).setPositiveButton("VERIFY OTP",null).create();dlg.setOnShowListener{dlg.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener{if(entry.text.toString()==otp.toString()){dlg.dismiss();draft.edit().putBoolean("historyConsentVerified",true).putString("historyConsentAt",System.currentTimeMillis().toString()).apply();render()}else entry.error="Incorrect OTP"}};dlg.show()}
 private fun historySummary():String{val id=selected?.optString("id").orEmpty();val rels=store.all(ArthSaathiV62Core.RELATIONSHIPS).filter{it.optString("counterpartyId")==id};val repayments=store.all(ArthSaathiV62Core.REPAYMENTS).filter{it.optString("counterpartyId")==id};val exposure=rels.sumOf{it.optDouble("amount",0.0)};val repaid=repayments.sumOf{it.optDouble("amount",0.0)};val score=(750-(rels.size*8)-(maxOf(0.0,exposure-repaid)/10000.0)).toInt().coerceIn(300,900);return "CONSENTED HISTORY\nRelationships: ${rels.size}\nRecorded exposure: ₹${"%.2f".format(Locale.US,exposure)}\nRecorded repayments: ₹${"%.2f".format(Locale.US,repaid)}\nArthSaathi Score (internal): $score"}
 private fun terms(){add(ArthSaathiV62Design.section(this,"2 • TERMS & REPAYMENT ENGINE"),8);val type=Spinner(this).apply{adapter=ArrayAdapter(this@V62CreditRegistrationActivity,android.R.layout.simple_spinner_dropdown_item,arrayOf("Personal / Hand Loan","Business Trade Credit — Supplier / Seller","Rental / Lease Credit","Other"))};val amount=i("Principal / invoice value ₹ *");val roi=i("Interest rate % — 0 = interest-free");val method=Spinner(this).apply{adapter=ArrayAdapter(this@V62CreditRegistrationActivity,android.R.layout.simple_spinner_dropdown_item,arrayOf("EMI","Principal + Interest","Bullet / single payment"))};val period=Spinner(this).apply{adapter=ArrayAdapter(this@V62CreditRegistrationActivity,android.R.layout.simple_spinner_dropdown_item,arrayOf("Monthly","Quarterly","Half-yearly","Yearly","One-time"))};val start=i("Start date DD/MM/YYYY");val end=i("End / final payment date DD/MM/YYYY");val emi=i("Auto-calculated EMI").apply{isFocusable=false};val bullet=Spinner(this).apply{adapter=ArrayAdapter(this@V62CreditRegistrationActivity,android.R.layout.simple_spinner_dropdown_item,arrayOf("No periodic interest","Interest monthly","Interest quarterly","Interest half-yearly","Interest yearly"))};listOf(ArthSaathiV62Design.text(this,"Credit type",10f,ArthSaathiV62Design.MUTED,true),type,amount,roi,start,end,ArthSaathiV62Design.text(this,"Repayment method",10f,ArthSaathiV62Design.MUTED,true),method,ArthSaathiV62Design.text(this,"Periodicity",10f,ArthSaathiV62Design.MUTED,true),period,emi,ArthSaathiV62Design.text(this,"Bullet interest servicing",10f,ArthSaathiV62Design.MUTED,true),bullet).forEach{add(it)};fun calc(){if(method.selectedItemPosition!=0){emi.setText("");return};val p=amount.text.toString().replace(",","").toDoubleOrNull();val r=roi.text.toString().toDoubleOrNull()?:0.0;val s=parse(start.text.toString());val e=parse(end.text.toString());val freq=when(period.selectedItemPosition){0->12;1->4;2->2;3->1;else->0};if(p==null||p<=0||s==null||e==null||!e.after(s)||freq==0){emi.setText("");return};val n=maxOf(1,Math.round(((e.time-s.time).toDouble()/(1000*60*60*24*30.4375))/(12.0/freq)).toInt());val rate=r/100/freq;val pay=if(rate==0.0)p/n else p*rate*(1+rate).pow(n)/((1+rate).pow(n)-1);emi.setText(String.format(Locale.US,"%.2f",pay))};val tw=object:android.text.TextWatcher{override fun beforeTextChanged(s:CharSequence?,a:Int,b:Int,c:Int){};override fun onTextChanged(s:CharSequence?,a:Int,b:Int,c:Int){calc()};override fun afterTextChanged(e:android.text.Editable?){}};amount.addTextChangedListener(tw);roi.addTextChangedListener(tw);start.addTextChangedListener(tw);end.addTextChangedListener(tw);method.onItemSelectedListener=spin{calc()};period.onItemSelectedListener=spin{calc()};add(ArthSaathiV62Design.text(this,"EMI is live-calculated. Principal + Interest and Bullet retain their distinct servicing terms.",10f,ArthSaathiV62Design.MUTED),8);add(ArthSaathiV62Design.button(this,"CONTINUE →",ArthSaathiV62Design.GREEN){draft.edit().putString("amount",amount.text.toString()).putString("roi",roi.text.toString()).putString("method",method.selectedItem.toString()).putString("period",period.selectedItem.toString()).putString("bulletInterest",bullet.selectedItem.toString()).putString("start",start.text.toString()).putString("end",end.text.toString()).putString("emi",emi.text.toString()).putString("type",type.selectedItem.toString()).apply();step=3;render()},12)}
 private fun evidence(){add(ArthSaathiV62Design.section(this,"3 • INVOICE / SUPPORTING DOCUMENT"),8);add(ArthSaathiV62Design.text(this,"For trade credit, attach the invoice or supporting evidence. Original evidence remains linked to the relationship.",10f,ArthSaathiV62Design.MUTED),5);add(ArthSaathiV62Design.button(this,"SCAN / ATTACH INVOICE",ArthSaathiV62Design.TEAL){pickDoc()},8);add(ArthSaathiV62Design.button(this,"ATTACH OTHER DOCUMENT",ArthSaathiV62Design.BLUE){pickDoc()},5);if(docUri.isNotBlank())add(ArthSaathiV62Design.text(this,"Original retained: $docUri",10f,ArthSaathiV62Design.GREEN,true),7);add(ArthSaathiV62Design.button(this,"REVIEW PROMISSORY NOTE →",ArthSaathiV62Design.GREEN){step=4;render()},12)}
 private fun consent(){add(ArthSaathiV62Design.section(this,"4 • PROMISSORY NOTE BEFORE CONSENT OTP"),8);val note="I, Mr./Ms. [YOUR NAME], promise to pay ${selected?.optString("name")} an amount of Rs. ${draft.getString("amount","")} plus interest at ${draft.getString("roi","0")}% per annum, according to the agreed repayment terms, on or before the applicable final payment date.\n\nRepayment method: ${draft.getString("method","")}\nPeriodicity: ${draft.getString("period","")}\nFinal date: ${draft.getString("end","")}";add(ArthSaathiV62Design.text(this,"PROMISSORY NOTE\n\n$note",13f,ArthSaathiV62Design.NAVY).apply{setPadding(ArthSaathiV62Design.dp(14,d),ArthSaathiV62Design.dp(14,d),ArthSaathiV62Design.dp(14,d),ArthSaathiV62Design.dp(14,d));background=ArthSaathiV62Design.card(ArthSaathiV62Design.WHITE,14,d)});add(ArthSaathiV62Design.button(this,"REQUEST CONSENT OTP",ArthSaathiV62Design.TEAL){registerAfterOtp(note)},10)}
 private fun registerAfterOtp(note:String){val otp=(100000..999999).random();val entry=i("Enter OTP");val dlg=AlertDialog.Builder(this).setTitle("Registration consent OTP").setMessage("Review the promissory note before authorising this registration.\n\nDemo OTP: $otp").setView(entry).setNegativeButton("CANCEL",null).setPositiveButton("VERIFY & REGISTER",null).create();dlg.setOnShowListener{dlg.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener{if(entry.text.toString()==otp.toString()){dlg.dismiss();register(note)}else entry.error="Invalid OTP"}};dlg.show()}
 private fun register(note:String){val rel=JSONObject().apply{put("id",ArthSaathiV62Core.id("REL"));put("myRole",draft.getString("myRole",""));put("counterRole",draft.getString("counterRole",""));put("counterpartyId",selected?.optString("id"));put("amount",draft.getString("amount","0").toDoubleOrNull()?:0.0);put("roi",draft.getString("roi","0").toDoubleOrNull()?:0.0);put("method",draft.getString("method",""));put("period",draft.getString("period","") );put("bulletInterest",draft.getString("bulletInterest","") );put("emi",draft.getString("emi","0").toDoubleOrNull()?:0.0);put("start",draft.getString("start",""));put("end",draft.getString("end",""));put("promissoryNote",note);put("status","ACTIVE");put("historyConsent","VERIFIED");put("registrationConsent","VERIFIED");put("createdAt",System.currentTimeMillis())};store.add(ArthSaathiV62Core.RELATIONSHIPS,rel);Toast.makeText(this,"Financial relationship registered successfully",Toast.LENGTH_LONG).show();draft.edit().clear().apply();finish()}
 private fun pickDoc(){startActivityForResult(Intent(Intent.ACTION_OPEN_DOCUMENT).apply{type="application/pdf";addCategory(Intent.CATEGORY_OPENABLE)},77)}
 override fun onActivityResult(r:Int,c:Int,data:Intent?){super.onActivityResult(r,c,data);if(r==77&&c==RESULT_OK&&data?.data!=null){docUri=ArthSaathiV62Core.saveDocument(this,data.data!!,"CREDIT").optString("uri");render()}}
 private fun parse(s:String)=runCatching{SimpleDateFormat("dd/MM/yyyy",Locale.getDefault()).parse(s)}.getOrNull();private fun spin(f:()->Unit)=object:AdapterView.OnItemSelectedListener{override fun onNothingSelected(p:AdapterView<*>?){};override fun onItemSelected(p:AdapterView<*>?,v:View?,pos:Int,id:Long){f()}}
}